using System.Net;
using System.Security.Cryptography;
using System.Text.Json;
using NullTV.Core;

internal static class UpdateTests
{
    internal static void Register(Action<string,Func<Task>> test,Action<bool,string> check)
    {
        var bytes=Enumerable.Range(0,180000).Select(n=>(byte)(n%251)).ToArray();
        var release=new UpdateRelease(1,"NullTV","0.5.0","arm64",22000,DateTimeOffset.UtcNow,"https://github.com/nulldev85/NullTV-updates/releases/download/v0.5.0/NullTV-Setup-arm64-0.5.0.msi",bytes.Length,Convert.ToHexString(SHA256.HashData(bytes)),"Smaller controls. A dedicated player. Built-in updates.");
        byte[] Manifest(UpdateRelease value,ECDsa key)=>JsonSerializer.SerializeToUtf8Bytes(new SignedUpdate(Convert.ToBase64String(JsonSerializer.SerializeToUtf8Bytes(value,UpdateTrust.Json)),Convert.ToBase64String(key.SignData(JsonSerializer.SerializeToUtf8Bytes(value,UpdateTrust.Json),HashAlgorithmName.SHA256))),UpdateTrust.Json);
        async Task Reject(Func<Task> action) { try { await action(); throw new Exception("Unsafe update accepted"); } catch(InvalidDataException) { } }
        test("Updates authenticate signed stable release and compare numeric versions",()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var pub=Convert.ToBase64String(key.ExportSubjectPublicKeyInfo()); var parsed=UpdateTrust.Verify(UpdateTrust.Sign(release,key),pub); check(parsed==release,"Signed release changed"); check(UpdateTrust.IsNewer(parsed,new(0,4,2),26200,"Arm64"),"New release missed"); check(!UpdateTrust.IsNewer(parsed,new(0,5,0),26200,"arm64") && !UpdateTrust.IsNewer(parsed,new(0,6,0),26200,"arm64"),"Downgrade accepted"); check(UpdateTrust.ParseVersion("0.10.0")>UpdateTrust.ParseVersion("0.9.0"),"Lexical version comparison"); return Task.CompletedTask; });
        test("Updates reject tampered payload and untrusted signer",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); using var stranger=ECDsa.Create(ECCurve.NamedCurves.nistP256); var pub=Convert.ToBase64String(key.ExportSubjectPublicKeyInfo()); var envelope=JsonSerializer.Deserialize<SignedUpdate>(UpdateTrust.Sign(release,key),UpdateTrust.Json)!; var payload=Convert.FromBase64String(envelope.Payload); payload[^3]^=1; await Reject(()=> { UpdateTrust.Verify(JsonSerializer.SerializeToUtf8Bytes(envelope with { Payload=Convert.ToBase64String(payload) },UpdateTrust.Json),pub); return Task.CompletedTask; }); await Reject(()=> { UpdateTrust.Verify(UpdateTrust.Sign(release,stranger),pub); return Task.CompletedTask; }); });
        test("Updates reject short signature and oversized manifest",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var pub=Convert.ToBase64String(key.ExportSubjectPublicKeyInfo()); var envelope=JsonSerializer.Deserialize<SignedUpdate>(UpdateTrust.Sign(release,key),UpdateTrust.Json)!; await Reject(()=> { UpdateTrust.Verify(JsonSerializer.SerializeToUtf8Bytes(envelope with { Signature=Convert.ToBase64String(new byte[32]) },UpdateTrust.Json),pub); return Task.CompletedTask; }); await Reject(()=> { UpdateTrust.Verify(new byte[UpdateTrust.MaximumManifestBytes+1],pub); return Task.CompletedTask; }); });
        test("Updates reject signed path escapes, alternate hosts and URL parameters",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var pub=Convert.ToBase64String(key.ExportSubjectPublicKeyInfo()); foreach(var url in new[]{"http://github.com/nulldev85/NullTV-updates/releases/download/v0.5.0/NullTV-Setup-arm64-0.5.0.msi",release.InstallerUrl+"?other=1",release.InstallerUrl.Replace("github.com","github.com.evil.invalid"),release.InstallerUrl.Replace("/NullTV-updates/","/Other/"),release.InstallerUrl.Replace("NullTV-Setup-arm64-0.5.0.msi","../other.msi")}) await Reject(()=> { UpdateTrust.Verify(Manifest(release with { InstallerUrl=url },key),pub); return Task.CompletedTask; }); });
        test("Updates reject invalid signed schema, architecture, size and versions",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var pub=Convert.ToBase64String(key.ExportSubjectPublicKeyInfo()); foreach(var invalid in new[]{release with { Schema=2 },release with { AppId="Other" },release with { Architecture="x64" },release with { Size=0 },release with { Size=2L*1024*1024*1024 },release with { Sha256="abc" },release with { Version="0.5.0-beta" },release with { Version="256.0.0" },release with { Version="01.5.0" },release with { MinimumWindowsBuild=19041 },release with { Notes=new string('x',24001) }}) await Reject(()=> { UpdateTrust.Verify(Manifest(invalid,key),pub); return Task.CompletedTask; }); });
        test("Update checks return available/current and reject incompatible OS",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var manifest=UpdateTrust.Sign(release,key); using var http=new HttpClient(new UpdateHandler(manifest,bytes)); var client=new UpdateClient(http,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())); check((await client.CheckAsync(new(0,4,2),26200,"arm64"))?.Release==release,"Available release missing"); check(await client.CheckAsync(new(0,5,0),26200,"arm64")==null,"Current release offered"); await Reject(()=>client.CheckAsync(new(0,4,2),19041,"arm64")); await Reject(()=>client.CheckAsync(new(0,4,2),26200,"x64")); });
        test("Update feed 404 never claims up to date",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); using var http=new HttpClient(new UpdateHandler(UpdateTrust.Sign(release,key),bytes) { Missing=true }); await Reject(()=>new UpdateClient(http,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())).CheckAsync(new(0,4,2),26200,"arm64")); });
        test("Update streaming download verifies hash and persists authenticated manifest",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var manifest=UpdateTrust.Sign(release,key); using var http=new HttpClient(new UpdateHandler(manifest,bytes)); var client=new UpdateClient(http,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())); var update=(await client.CheckAsync(new(0,4,2),26200,"arm64"))!; var dir=Path.Combine(Path.GetTempPath(),"NullTV-update-"+Guid.NewGuid().ToString("N")); try { var progress=new CollectProgress(); var path=await client.DownloadAsync(update,dir,progress); await UpdateClient.VerifyPackageAsync(path,release); check(File.ReadAllBytes(path).SequenceEqual(bytes),"Download bytes changed"); check(File.ReadAllBytes(Path.Combine(dir,"update.json")).SequenceEqual(manifest),"Manifest changed"); check(progress.Last?.Received==release.Size && progress.Last.Total==release.Size,"Progress incorrect"); check(!Directory.GetFiles(dir,"*.part").Any(),"Partial file retained"); } finally { Directory.Delete(dir,true); } });
        test("Update corrupt and truncated downloads leave no installable package",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var manifest=UpdateTrust.Sign(release,key); foreach(var data in new[]{bytes.Select((b,n)=>(byte)(n==100 ? b^1 : b)).ToArray(),bytes[..^100]}) { using var http=new HttpClient(new UpdateHandler(manifest,data) { OmitLength=true }); var client=new UpdateClient(http,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())); var dir=Path.Combine(Path.GetTempPath(),"NullTV-update-"+Guid.NewGuid().ToString("N")); try { await Reject(()=>client.DownloadAsync(new(release,manifest),dir,null)); check(!Directory.GetFiles(dir).Any(),"Unsafe downloaded file retained"); } finally { Directory.Delete(dir,true); } } });
        test("Update oversized download is bounded and cleaned up",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var manifest=UpdateTrust.Sign(release,key); using var http=new HttpClient(new UpdateHandler(manifest,[..bytes,1,2,3]) { OmitLength=true }); var dir=Path.Combine(Path.GetTempPath(),"NullTV-update-"+Guid.NewGuid().ToString("N")); try { await Reject(()=>new UpdateClient(http,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())).DownloadAsync(new(release,manifest),dir,null)); check(!Directory.GetFiles(dir).Any(),"Oversized file retained"); } finally { Directory.Delete(dir,true); } });
        test("Update download cancellation leaves no package",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var manifest=UpdateTrust.Sign(release,key); using var http=new HttpClient(new UpdateHandler(manifest,bytes)); using var cancelled=new CancellationTokenSource(); cancelled.Cancel(); var dir=Path.Combine(Path.GetTempPath(),"NullTV-update-"+Guid.NewGuid().ToString("N")); try { try { await new UpdateClient(http,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())).DownloadAsync(new(release,manifest),dir,null,cancelled.Token); throw new Exception("Cancellation ignored"); } catch(OperationCanceledException) { } check(!Directory.GetFiles(dir).Any(),"Cancelled package retained"); } finally { Directory.Delete(dir,true); } });
        test("Update caller cannot alter authenticated release details",async ()=> { using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256); var manifest=UpdateTrust.Sign(release,key); using var http=new HttpClient(new UpdateHandler(manifest,bytes)); await Reject(()=>new UpdateClient(http,Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())).DownloadAsync(new(release with { Notes="Altered" },manifest),Path.GetTempPath(),null)); });
        test("Update file changes are caught before installation",async ()=> { var path=Path.Combine(Path.GetTempPath(),"NullTV-update-"+Guid.NewGuid().ToString("N")+".msi"); try { await File.WriteAllBytesAsync(path,bytes); await UpdateClient.VerifyPackageAsync(path,release); var altered=bytes.ToArray(); altered[100]^=1; await File.WriteAllBytesAsync(path,altered); await Reject(()=>UpdateClient.VerifyPackageAsync(path,release)); } finally { File.Delete(path); } });
        test("Update preferences round trip without changing profile data",()=> { var original=new Settings { CheckUpdatesOnStartup=false,LastUpdateCheckUtc=DateTimeOffset.UtcNow,DismissedUpdateVersion="0.5.0" }; original.Profile.Favorites.Add("channel"); var restored=JsonSerializer.Deserialize<Settings>(JsonSerializer.Serialize(original,SettingsStore.JsonOptions),SettingsStore.JsonOptions)!; restored.Validate(); check(!restored.CheckUpdatesOnStartup && restored.LastUpdateCheckUtc==original.LastUpdateCheckUtc && restored.DismissedUpdateVersion=="0.5.0" && restored.Profile.Favorites.Contains("channel"),"Preferences or profile lost"); return Task.CompletedTask; });
    }
    private sealed class CollectProgress : IProgress<UpdateDownload> { public UpdateDownload? Last; public void Report(UpdateDownload value)=>Last=value; }
    private sealed class UpdateHandler(byte[] manifest,byte[] package) : HttpMessageHandler
    {
        public bool Missing,OmitLength;
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct)
        {
            ct.ThrowIfCancellationRequested(); var data=request.RequestUri!.AbsolutePath.EndsWith("update.json") ? manifest : package;
            HttpContent content=OmitLength ? new StreamContent(new NonSeekable(data)) : new ByteArrayContent(data);
            return Task.FromResult(new HttpResponseMessage(Missing ? HttpStatusCode.NotFound : HttpStatusCode.OK) { Content=content });
        }
    }
    private sealed class NonSeekable(byte[] bytes) : MemoryStream(bytes) { public override bool CanSeek=>false; }
}
